                assert_eq!(edited.dialogs.iter().find(|dialog| dialog.guest_id == pinned.identity.0).unwrap().items[6].text, before.items[6].text);
                worker.0.send(Command::ReplaceText(owner.clone(), range, bytes, None)).unwrap();
